const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const fmt=(n,d=2)=>Number(n||0).toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d});
const money=n=>(Number(n||0)>=0?'+':'')+fmt(n);
const monthLabel=m=>{const [y,mo]=String(m).split('-');return new Date(Number(y),Number(mo)-1,1).toLocaleDateString('pt-BR',{month:'short'}).replace('.','')};
function set(id,v){const e=document.getElementById(id);if(e)e.textContent=v}
let dashboardData=null,metricData=null,filterData=null;
const APP_VERSION='V53';
let recentPage=1;
let recentPageSize=20;
let editingFilterId=null;

function renderCurve(c){
 const svg=$('#curve'); if(!svg)return;
 if(!c?.length){svg.innerHTML='<text x="50%" y="50%" text-anchor="middle" fill="#73849a">Sem dados para exibir</text>';return;}
 const w=700,h=260,p=28,vals=c.map(x=>Number(x.acumulado||0));
 const rawMin=Math.min(0,...vals),rawMax=Math.max(0,...vals);
 const range=Math.max(rawMax-rawMin,1),pad=range*0.08;
 const min=rawMin<0?rawMin-pad:0, max=rawMax>0?rawMax+pad:0, scale=Math.max(max-min,1);
 const xAt=i=>p+(w-2*p)*i/Math.max(1,c.length-1), yAt=v=>h-p-(v-min)/scale*(h-2*p), zero=yAt(0);
 const pts=c.map((x,i)=>[xAt(i),yAt(Number(x.acumulado||0))]);
 const labels=[min,max].filter((v,i,a)=>a.indexOf(v)===i).map(v=>`<text x="4" y="${yAt(v)+3}" class="axisLabel">${esc(fmt(v,0))}</text>`).join('');
 let segments='';
 for(let i=1;i<pts.length;i++){
   const a=pts[i-1],b=pts[i], va=vals[i-1],vb=vals[i], positive=vb>=0&&va>=0, negative=vb<0&&va<0;
   let color=positive?'#55e68a':negative?'#ff6870':'#b8c4d3';
   segments+=`<line x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}" stroke="${color}" stroke-width="3" stroke-linecap="round"/>`;
 }
 svg.innerHTML=`<line class="zeroLine" x1="${p}" y1="${zero}" x2="${w-p}" y2="${zero}"/><text x="${w-p+5}" y="${zero+3}" class="zeroLabel">0</text>${labels}${segments}`;
}
function renderBlocks(blocks){
 const tabs=$('#blockTabs'),body=$('#blockBody');
 if(!tabs||!body)return;
 const bs=blocks||[];
 tabs.innerHTML=bs.length?bs.map(b=>`<button class="blockTab" data-block="${b.bloco}"><b>Bloco ${b.bloco}</b><small>${b.inicio}-${b.fim} • ${b.entries} jogos</small></button>`).join(''):'<span class="muted">Nenhum bloco disponível.</span>';
 body.innerHTML=bs.map(b=>`<tr><td>Bloco ${b.bloco}</td><td>${b.entries}</td><td class="positive">${b.greens}</td><td class="negative">${b.reds}</td><td>${fmt(b.winrate,1)}%</td><td>${fmt(b.oddMedia,2)}</td><td class="${b.lucro>=0?'positive':'negative'}">${money(b.lucro)}</td><td class="${b.roi>=0?'positive':'negative'}">${fmt(b.roi,1)}%</td></tr>`).join('')||emptyRow(8,'Nenhum jogo passou pelo recorte.');
 tabs.querySelectorAll('.blockTab').forEach(btn=>btn.addEventListener('click',()=>{tabs.querySelectorAll('.blockTab').forEach(x=>x.classList.remove('active'));btn.classList.add('active');const n=Number(btn.dataset.block);const row=bs.find(x=>x.bloco===n);if(row)body.innerHTML=`<tr><td>Bloco ${row.bloco}</td><td>${row.entries}</td><td class="positive">${row.greens}</td><td class="negative">${row.reds}</td><td>${fmt(row.winrate,1)}%</td><td>${fmt(row.oddMedia,2)}</td><td class="${row.lucro>=0?'positive':'negative'}">${money(row.lucro)}</td><td class="${row.roi>=0?'positive':'negative'}">${fmt(row.roi,1)}%</td></tr>`;}));
 if(bs[0])tabs.querySelector('.blockTab')?.classList.add('active');
}
function renderRecent(rows){
 const body=$('#recentBody'),pag=$('#recentPagination'),summary=$('#recentSummary'); if(!body||!pag)return;
 const all=Array.isArray(rows)?rows:[], total=all.length, pages=Math.max(1,Math.ceil(total/recentPageSize)); recentPage=Math.min(Math.max(1,recentPage),pages);
 const slice=all.slice().reverse().slice((recentPage-1)*recentPageSize,recentPage*recentPageSize);
 body.innerHTML=slice.map((x,i)=>`<tr><td>${(recentPage-1)*recentPageSize+i+1}</td><td>${esc(x.DATA)}</td><td>${esc(x.CONFRONTO)}</td><td>${esc(x.CAMPEONATO)}</td><td>${esc(x.mercado_label)}</td><td>${fmt(x.odd)}</td><td><b class="pill ${x.green?'green':'red'}">${x.green?'Green':'Red'}</b></td><td class="${x.pnl>=0?'positive':'negative'}">${money(x.pnl)}</td></tr>`).join('')||emptyRow(8,'Nenhuma entrada encontrada.');
 if(summary)summary.textContent=`${total.toLocaleString('pt-BR')} entradas • ${recentPageSize} por página`;
 const btns=[];btns.push(`<button class="secondary pageBtn" data-page="${Math.max(1,recentPage-1)}" ${recentPage<=1?'disabled':''}>‹</button>`);
 const windowPages=[];for(let i=1;i<=pages;i++){if(i<=3||i===pages||Math.abs(i-recentPage)<=1)windowPages.push(i);else if(windowPages.at(-1)!=='…')windowPages.push('…');}
 windowPages.forEach(i=>btns.push(i==='…'?'<span class="pageEllipsis">…</span>':`<button class="secondary pageBtn${i===recentPage?' active':''}" data-page="${i}">${i}</button>`));
 btns.push(`<button class="secondary pageBtn" data-page="${Math.min(pages,recentPage+1)}" ${recentPage>=pages?'disabled':''}>›</button>`);pag.innerHTML=btns.join('');pag.querySelectorAll('.pageBtn').forEach(b=>b.addEventListener('click',()=>{recentPage=Number(b.dataset.page);renderRecent(dashboardData?.rows||[]);}));
}
function renderDashboard(d){
 dashboardData=d;set('entries',Number(d.entries||0).toLocaleString('pt-BR'));set('winrate',fmt(d.winrate,1)+'%');set('avgodd',fmt(d.oddMedia,2));set('profit',money(d.lucro));set('roi',fmt(d.roi,1)+'%');set('dd','-'+fmt(Math.abs(d.drawdown)));set('fairOdd',d.fairOddMedia==null?'0,00':fmt(d.fairOddMedia,2));set('fairProfit',money(d.lucroJustoLiquido||0));set('fairROI',fmt(d.roiJustoLiquido||0,1)+'%');$('#profit')?.classList.toggle('negative',d.lucro<0);$('#profit')?.classList.toggle('positive',d.lucro>=0);renderCurve(d.curve||[]);
 const mb=$('#monthlyBars'),ml=$('#monthlyLabels');if(mb&&ml){mb.innerHTML='';ml.innerHTML='';const mx=Math.max(1,...(d.monthly||[]).map(x=>Math.abs(x.lucro)));(d.monthly||[]).forEach(x=>{const b=document.createElement('span');b.style.height=Math.max(6,Math.abs(x.lucro)/mx*100)+'%';if(x.lucro<0)b.classList.add('red');b.title=`${x.mes}: ${money(x.lucro)}`;mb.appendChild(b);const l=document.createElement('small');l.textContent=monthLabel(x.mes);ml.appendChild(l)})}
 const champs=d.championships||[];if($('#champBody'))$('#champBody').innerHTML=champs.map(champRow).join('')||emptyRow(5,'Nenhum campeonato no recorte.');const total=d.entries||1;if($('#donut'))$('#donut').style.setProperty('--green',((d.distributions?.green||0)/total*100)+'%');set('distTotal',Number(d.entries||0).toLocaleString('pt-BR'));set('greenCount','Green '+(d.distributions?.green||0));set('redCount','Red '+(d.distributions?.red||0));
 renderBlocks(d.blocks||[]);recentPage=1;renderRecent(d.rows||[]);
 if($('#champReportBody'))$('#champReportBody').innerHTML=champs.map(x=>`<tr><td>${esc(x.nome)}</td><td>${x.entries}</td><td class="positive">${x.greens}</td><td class="negative">${x.reds}</td><td>${fmt(x.winrate,1)}%</td><td>${fmt(x.oddMedia,2)}</td><td class="${x.lucro>=0?'positive':'negative'}">${money(x.lucro)}</td><td class="${x.roi>=0?'positive':'negative'}">${fmt(x.roi,1)}%</td></tr>`).join('')||emptyRow(8,'Nenhum campeonato encontrado.');
 const mm=$('#marketListBottom');if(mm){const selected=String(d.market||'');mm.innerHTML=`<div class="marketSummaryHead"><span>Mercado</span><span>Entradas</span><span>Winrate</span><span>P/L (${d.pnlRef==='JUSTA'?'Justa':'365'})</span><span>ROI</span><span>Odd justa</span><span>P/L justo</span><span>ROI justo</span></div>`+(d.markets||[]).map(x=>{const active=String(x.mercado)===selected;return `<div class="marketSummaryRow${active?' selected':''}"><b>${esc(x.label)}</b><span>${x.entries}</span><span>${fmt(x.winrate,1)}%</span><span class="${x.lucro>=0?'positive':'negative'}">${money(x.lucro)}</span><span class="${x.roi>=0?'positive':'negative'}">${fmt(x.roi,1)}%</span><span>${x.oddJustaMedia==null?'—':fmt(x.oddJustaMedia,2)}</span><span class="${(x.lucroJustoLiquido||0)>=0?'positive':'negative'}">${x.lucroJustoLiquido==null?'—':money(x.lucroJustoLiquido)}</span><span class="${(x.roiJustoLiquido||0)>=0?'positive':'negative'}">${x.roiJustoLiquido==null?'—':fmt(x.roiJustoLiquido,1)+'%'}</span></div>`}).join('')||'<span class="muted">Nenhum mercado disponível.</span>'}
}
function champRow(x){return `<tr><td>${esc(x.nome)}</td><td>${x.entries}</td><td>${fmt(x.winrate,1)}%</td><td class="${x.lucro>=0?'positive':'negative'}">${money(x.lucro)}</td><td>${fmt(x.roi,1)}%</td></tr>`}
function emptyRow(cols,msg){return `<tr><td colspan="${cols}" class="muted">${esc(msg)}</td></tr>`}
async function api(path,opts={}){const r=await fetch(path,{cache:'no-store',...opts});let d={};try{d=await r.json()}catch{}if(!r.ok)throw Error(d.error||d.detail||JSON.stringify(d));return d}
function champPickerValues(id){const box=$(id);if(!box)return[];const all=box.querySelector('input[data-all="1"]');if(all?.checked)return[];return [...box.querySelectorAll('input[data-champ="1"]:checked')].map(x=>x.value).filter(Boolean)}
function setChampPicker(id,values=[],disabled=false){const box=$(id);if(!box)return;const vals=new Set((values||[]).map(String));const all=box.querySelector('input[data-all="1"]');const items=[...box.querySelectorAll('input[data-champ="1"]')];const has=vals.size>0;items.forEach(x=>{x.checked=has&&vals.has(String(x.value));x.disabled=disabled});if(all){all.checked=!has;all.disabled=disabled}box.classList.toggle('disabled',disabled);updateChampPickerSummary(id)}
function renderChampPicker(id,vals,selected=[],disabled=false){const box=$(id);if(!box)return;box.innerHTML=`<button type="button" class="pickerTrigger"><span class="pickerSummary">Todos os campeonatos</span><span class="pickerChevron">▾</span></button><div class="pickerMenu"><label class="pickerAll"><input type="checkbox" data-all="1"> <b>Todos</b></label><div class="pickerItems">${(vals||[]).map(v=>`<label><input type="checkbox" data-champ="1" value="${esc(v)}"> <span>${esc(v)}</span></label>`).join('')}</div></div>`;const trigger=box.querySelector('.pickerTrigger');const menu=box.querySelector('.pickerMenu');trigger?.addEventListener('click',e=>{e.preventDefault();if(trigger.disabled)return;document.querySelectorAll('.champPicker .pickerMenu.open').forEach(m=>{if(m!==menu)m.classList.remove('open')});menu?.classList.toggle('open')});const all=box.querySelector('input[data-all="1"]');all?.addEventListener('change',()=>{if(all.checked)box.querySelectorAll('input[data-champ="1"]').forEach(x=>x.checked=false);updateChampPickerSummary(id)});box.querySelectorAll('input[data-champ="1"]').forEach(x=>x.addEventListener('change',()=>{if(x.checked&&all)all.checked=false;const any=box.querySelector('input[data-champ="1"]:checked');if(!any&&all)all.checked=true;updateChampPickerSummary(id)}));setChampPicker(id,selected,disabled)}
document.addEventListener('click',e=>{if(!e.target.closest('.champPicker'))document.querySelectorAll('.champPicker .pickerMenu.open').forEach(m=>m.classList.remove('open'))});
function updateChampPickerSummary(id){const box=$(id);if(!box)return;const disabled=box.classList.contains('disabled');const all=box.querySelector('input[data-all="1"]');const vals=[...box.querySelectorAll('input[data-champ="1"]:checked')];const label=box.querySelector('.pickerSummary');if(label)label.textContent=disabled?(vals.length?`${vals.length} campeonato(s) definidos pelo filtro`:'Todos os campeonatos definidos pelo filtro'):(all?.checked||!vals.length?'Todos os campeonatos':`${vals.length} campeonato(s) selecionado(s)`);const trigger=box.querySelector('.pickerTrigger');if(trigger)trigger.disabled=disabled;const menu=box.querySelector('.pickerMenu');if(disabled)menu?.classList.remove('open')}
async function dash(){
 const btn=$('#apply');
 const market=$('#market')?.value||'OVER_2_5';
 const pnlRef=$('#pnlRef')?.value||'365';
 const filterName=$('#dashFilter')?.selectedOptions?.[0]?.textContent||'Sem filtro';
 if(btn){btn.disabled=true;btn.classList.add('loading');btn.innerHTML='<span class="spinner"></span> Aplicando...';}
 set('sideStatus','Atualizando...');
 set('configStatus',`Aplicando • ${market} • ${filterName}`);
 try{
  const q=new URLSearchParams({temporada:$('#season').value||'Todos',campeonato:'Todos',campeonatos:JSON.stringify(champPickerValues('#dashChampPicker')),mercado:market,pnl_ref:pnlRef,filtro_id:$('#dashFilter')?.value||'',comissao:localStorage.getItem('sofa_comissao')||'4.5'});
  const d=await api('/api/dashboard?'+q);
  renderDashboard(d);
  if(d.filter){setChampPicker('#dashChampPicker',d.filter.campeonatos||[],Boolean((d.filter.campeonatos||[]).length));}
  set('sideStatus','Conectado');
  set('configStatus',d.filter?.nome?`Banco B conectado • ${d.filter.nome} • ${d.marketLabel}`:`Banco B conectado • ${d.marketLabel}`);
 }catch(e){
  set('sideStatus','Erro');
  set('configStatus','Erro: '+e.message);
  throw e;
 }finally{
  if(btn){btn.disabled=false;btn.classList.remove('loading');btn.textContent='Aplicar';}
 }
}
async function options(){const d=await api('/api/dashboard?action=options');const fill=(id,vals)=>{const e=$(id);if(!e)return;e.innerHTML='<option>Todos</option>'+(vals||[]).map(x=>`<option>${esc(x)}</option>`).join('')};fill('#season',d.seasonsAvailable);fill('#btSeason',d.seasonsAvailable);fill('#btChamp',d.championshipsAvailable);renderChampPicker('#dashChampPicker',d.championshipsAvailable);renderChampPicker('#filterChampPicker',d.championshipsAvailable)}
function metricOptions(){return (metricData?.metricas||[]).filter(x=>x.ativa!==false&&x.ativo!==false).map(x=>`<option value="${x.id}" data-campo="${esc(x.campo||'')}">${esc(x.nome||x.name||('Métrica '+x.id))}</option>`).join('')}
const OFFICIAL_FIELDS=[
['RATING_CASA','Rating Casa'],['RATING_VISITANTE','Rating Visitante'],['GOLS_CASA_FT','Gols Casa FT'],['GOLS_VISITANTE_FT','Gols Visitante FT'],['XG_CASA','xG Casa'],['XG_VISITANTE','xG Visitante'],['XG_NO_ALVO_CASA','xG no alvo Casa'],['XG_NO_ALVO_VISITANTE','xG no alvo Visitante'],['FINALIZACOES_TOTAIS_CASA','Finalizações totais Casa'],['FINALIZACOES_TOTAIS_VISITANTE','Finalizações totais Visitante'],['FINALIZACOES_NO_ALVO_CASA','Finalizações no alvo Casa'],['FINALIZACOES_NO_ALVO_VISITANTE','Finalizações no alvo Visitante'],['FINALIZACOES_FORA_ALVO_CASA','Finalizações fora do alvo Casa'],['FINALIZACOES_FORA_ALVO_VISITANTE','Finalizações fora do alvo Visitante'],['FINALIZACOES_BLOQUEADAS_CASA','Finalizações bloqueadas Casa'],['FINALIZACOES_BLOQUEADAS_VISITANTE','Finalizações bloqueadas Visitante'],['ESCANTEIOS_CASA','Escanteios Casa'],['ESCANTEIOS_VISITANTE','Escanteios Visitante'],['POSSE_BOLA_CASA','Posse de bola Casa'],['POSSE_BOLA_VISITANTE','Posse de bola Visitante'],['PASSES_TOTAIS_CASA','Passes totais Casa'],['PASSES_TOTAIS_VISITANTE','Passes totais Visitante'],['PASSES_CERTOS_CASA','Passes certos Casa'],['PASSES_CERTOS_VISITANTE','Passes certos Visitante'],['PASSES_LONGOS_CERTOS_CASA','Passes longos certos Casa'],['PASSES_LONGOS_CERTOS_VISITANTE','Passes longos certos Visitante'],['CRUZAMENTOS_CERTOS_CASA','Cruzamentos certos Casa'],['CRUZAMENTOS_CERTOS_VISITANTE','Cruzamentos certos Visitante'],['TOQUES_AREA_ADVERSARIA_CASA','Toques na área adversária Casa'],['TOQUES_AREA_ADVERSARIA_VISITANTE','Toques na área adversária Visitante'],['ENTRADAS_TERCO_FINAL_CASA','Entradas no terço final Casa'],['ENTRADAS_TERCO_FINAL_VISITANTE','Entradas no terço final Visitante'],['DESARMES_TOTAIS_CASA','Desarmes totais Casa'],['DESARMES_TOTAIS_VISITANTE','Desarmes totais Visitante'],['PCT_DESARMES_GANHOS_CASA','% Desarmes ganhos Casa'],['PCT_DESARMES_GANHOS_VISITANTE','% Desarmes ganhos Visitante'],['INTERCEPTACOES_CASA','Interceptações Casa'],['INTERCEPTACOES_VISITANTE','Interceptações Visitante'],['RECUPERACOES_BOLA_CASA','Recuperações de bola Casa'],['RECUPERACOES_BOLA_VISITANTE','Recuperações de bola Visitante'],['CORTES_CLEARANCES_CASA','Cortes/Clearances Casa'],['CORTES_CLEARANCES_VISITANTE','Cortes/Clearances Visitante'],['PCT_DUELOS_GANHOS_CASA','% Duelos ganhos Casa'],['PCT_DUELOS_GANHOS_VISITANTE','% Duelos ganhos Visitante'],['DESARMES_SOFRIDOS_CASA','Desarmes sofridos Visitante'],['DESARMES_SOFRIDOS_VISITANTE','Desarmes sofridos Visitante']];
function fieldOptions(){const src=Array.isArray(metricData?.campose)&&metricData.campose.length?metricData.campose:OFFICIAL_FIELDS.map(([campo,nome])=>({campo,nome}));return src.map(x=>{const v=x.campo||x.field||x.nome||x.name||'';const label=x.nome||x.label||v;return v?`<option value="${esc(v)}">${esc(label)}${label!==v?' — '+esc(v):''}</option>`:''}).join('')}
async function loadMetrics(){const mf=$('#metricField');try{metricData=await api('/api/dashboard?action=metrics');set('metricMsg','');}catch(err){metricData={metricas:[],campose:OFFICIAL_FIELDS.map(([campo,nome])=>({campo,nome}))};set('metricMsg','API de métricas indisponível; campos oficiais carregados localmente.');}const ms=metricData.metricas||[];set('metricCount',ms.length+' métricas/configurações');if($('#metricBody'))$('#metricBody').innerHTML=ms.map(x=>{const active=x.ativa??x.ativo??true;const canManage=x.fonte==='metricas_config'||x.campo!==undefined;return `<tr><td>${x.id??''}</td><td>${esc(x.nome||x.name||'')}</td><td>${esc(x.campo||x.field||'')}</td><td>${esc(x.contexto||'')}</td><td>${x.janela_jogos??x.janela??''}</td><td>${x.minimo_jogos??x.minimo??''}</td><td>${esc(x.operacao||'')}</td><td><b class="pill ${active?'green':'red'}">${active?'Ativa':'Inativa'}</b></td><td>${canManage?`<button class="secondary metricEdit" data-id="${x.id}">Editar</button> <button class="secondary metricToggle" data-id="${x.id}" data-active="${active}">${active?'Desativar':'Ativar'}</button>${x.fonte==='metricas_config'?` <button class="remove metricDelete" data-id="${x.id}">Excluir</button>`:''}`:'—'}</td></tr>`}).join('')||emptyRow(9,'Nenhuma métrica cadastrada. Crie a primeira acima.');if(mf)mf.innerHTML='<option value="">Selecione um campo</option>'+fieldOptions()+`<option value="CUSTO_PONTO">CUSTO_PONTO — Custo do Ponto</option>`;$$('.metricSelect').forEach(e=>e.innerHTML='<option value="">Selecione uma métrica</option>'+metricOptions());}
async function editMetric(id){const x=(metricData?.metricas||[]).find(m=>String(m.id)===String(id));if(!x||x.fonte!=='metricas_config'){set('metricMsg','Esta métrica não pode ser editada.');return;}window.metricEditingId=Number(id);$('#metricName').value=x.nome||'';$('#metricDescription').value=x.descricao||'';const tipo=(x.formula?.tipo||((x.campo||'')==='COMPOSTA'?'COMPOSTA':(x.campo||'')==='CUSTO_PONTO'?'CUSTO_PONTO':'NORMAL')).toUpperCase();$('#metricType').value=tipo;if(tipo==='COMPOSTA'){syncMetricBuilder();$('#metricCompositeOperation').value=x.formula?.operacao||x.operacao||'MEDIA';const comps=x.formula?.componentes||[];$('#metricComponents').innerHTML='';comps.forEach(()=>addMetricComponent());$$('.compMetric').forEach((e,i)=>e.value=String(comps[i]?.metrica_id||''));}else{syncMetricBuilder();$('#metricField').value=x.campo||'';$('#metricContext').value=x.contexto||'CASA';$('#metricOperation').value=x.operacao||'MEDIA';$('#metricWindow').value=x.janela_jogos??x.janela??5;$('#metricMinimum').value=x.minimo_jogos??x.minimo??3;}const b=$('#saveMetric');if(b)b.textContent='Salvar alterações';set('metricMsg',`Editando métrica #${id}. Altere os campos e salve.`);document.querySelector('#page-metricas')?.scrollIntoView({behavior:'smooth',block:'start'});}
async function saveMetric(){const nome=$('#metricName').value.trim(),tipo=$('#metricType').value;if(!nome){set('metricMsg','Informe o nome da métrica.');return}let body={nome,descricao:$('#metricDescription').value.trim(),tipo};if(tipo==='COMPOSTA'){const comps=$$('.metricComponent').map(x=>({metrica_id:Number(x.querySelector('.compMetric').value)})).filter(x=>x.metrica_id>0);const op=$('#metricCompositeOperation')?.value||'MEDIA';if(comps.length<2){set('metricMsg','Adicione pelo menos 2 métricas à composição.');return}if(new Set(comps.map(x=>x.metrica_id)).size!==comps.length){set('metricMsg','Não repita a mesma métrica na composição.');return}body.campo='COMPOSTA';body.contexto='GERAL';body.janela_jogos=1;body.minimo_jogos=1;body.operacao=op;body.componentes=comps;}else{let campo=$('#metricField').value;if(tipo==='CUSTO_PONTO')campo='CUSTO_PONTO';if(!campo){set('metricMsg','Selecione um campo.');return}body.campo=campo;body.contexto=$('#metricContext').value;body.janela_jogos=Number($('#metricWindow').value||5);body.minimo_jogos=Number($('#metricMinimum').value||3);body.operacao=$('#metricOperation').value;}const payload=encodeURIComponent(JSON.stringify(body));set('metricMsg',window.metricEditingId?'Salvando alterações...':'Salvando...');const action=window.metricEditingId?`update_metric&id=${window.metricEditingId}&payload=${payload}`:`save_metric&payload=${payload}`;await api('/api/dashboard?action='+action);set('metricMsg',window.metricEditingId?'✓ Métrica atualizada no Banco B.':'✓ Métrica salva no Banco B.');window.metricEditingId=null;await loadMetrics();$$('.metricSelect').forEach(e=>e.innerHTML='<option value="">Selecione uma métrica</option>'+metricOptions());clearMetric(true);}
