 if(!nodes.length)addCondition(); const b=$('#saveFilter');if(b)b.textContent='Salvar alterações';set('filterMsg',`Editando filtro #${id}. Altere as condições e salve.`);document.querySelector('#page-filtros')?.scrollIntoView({behavior:'smooth',block:'start'});
