function normalizeImportHeader(h){return String(h??'').replace(/\ufeff/g,'').trim().toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[()\-\/]/g,' ').replace(/\s+/g,' ').trim()}
async function parseImportFile(file){
 const name=String(file?.name||'').toLowerCase();
 if(!file)throw Error('Nenhum arquivo selecionado.');
 if(typeof XLSX==='undefined')throw Error('Leitor de planilhas não carregado. Recarregue a página e tente novamente.');
 const buf=await file.arrayBuffer();
 let wb;
 try{wb=XLSX.read(buf,{type:'array',cellDates:false,raw:false});}catch(e){throw Error('Não consegui ler este arquivo. Use XLSX, CSV, TSV ou TXT.');}
 const sheet=wb.Sheets[wb.SheetNames[0]];
 if(!sheet)throw Error('O arquivo não possui uma planilha válida.');
 const matrix=XLSX.utils.sheet_to_json(sheet,{header:1,defval:'',raw:false});
 const rows0=matrix.filter(r=>Array.isArray(r)&&r.some(v=>String(v??'').trim()!==''));
 if(!rows0.length)throw Error('O arquivo está vazio.');
 const headers=rows0[0].map(v=>String(v??'').trim());
 if(headers.length<2)throw Error('Não consegui identificar as colunas do arquivo.');
 const rows=[];
 for(let i=1;i<rows0.length;i++){const vals=rows0[i];if(!vals.some(v=>String(v??'').trim()!==''))continue;const r={};headers.forEach((h,j)=>r[h]=String(vals[j]??'').trim());rows.push(r)}
 return{headers,rows};
}
const IMPORT_ALIASES={
 'data':'DATA','date':'DATA','hora':'HORA','time':'HORA','confronto':'CONFRONTO','campeonato':'CAMPEONATO','competicao':'CAMPEONATO','temporada':'TEMPORADA',
 'gols casa ht':'GOLS_CASA_HT','gols visitante ht':'GOLS_VISITANTE_HT','gols casa ft':'GOLS_CASA_FT','gols visitante ft':'GOLS_VISITANTE_FT',
 'odds casa':'ODD_1X2_CASA','odd casa':'ODD_1X2_CASA','odds empate':'ODD_1X2_EMPATE','odd empate':'ODD_1X2_EMPATE','odds visitante':'ODD_1X2_VISITANTE','odd visitante':'ODD_1X2_VISITANTE',
 'over ht':'ODD_OVER_HT','over 0 5':'ODD_OVER_0_5','under 0 5':'ODD_UNDER_0_5','over 1 5':'ODD_OVER_1_5','under 1 5':'ODD_UNDER_1_5','over 2 5':'ODD_OVER_2_5','under 2 5':'ODD_UNDER_2_5','over 3 5':'ODD_OVER_3_5','under 3 5':'ODD_UNDER_3_5',
 'btts sim':'ODD_BTTS_SIM','btts nao':'ODD_BTTS_NAO','btts sim ft':'ODD_BTTS_SIM','btts nao ft':'ODD_BTTS_NAO',
 'lg score casa':'LG_SCORE_CASA','lg score visitante':'LG_SCORE_VISITANTE','hscore':'HSCORE','lg score':'LG_SCORE',
 'odd justa over 0 5':'ODD_JUSTA_OVER_0_5','odd justa under 0 5':'ODD_JUSTA_UNDER_0_5','odd justa over 1 5':'ODD_JUSTA_OVER_1_5','odd justa under 1 5':'ODD_JUSTA_UNDER_1_5','odd justa over 2 5':'ODD_JUSTA_OVER_2_5','odd justa under 2 5':'ODD_JUSTA_UNDER_2_5','odd justa over 3 5':'ODD_JUSTA_OVER_3_5','odd justa under 3 5':'ODD_JUSTA_UNDER_3_5'
};
const IMPORT_KNOWN=new Set(['DATA','HORA','CONFRONTO','CAMPEONATO','TEMPORADA','GOLS_CASA_HT','GOLS_VISITANTE_HT','GOLS_CASA_FT','GOLS_VISITANTE_FT','ODD_1X2_CASA','ODD_1X2_EMPATE','ODD_1X2_VISITANTE','ODD_OVER_HT','ODD_OVER_0_5','ODD_UNDER_0_5','ODD_OVER_1_5','ODD_UNDER_1_5','ODD_OVER_2_5','ODD_UNDER_2_5','ODD_OVER_3_5','ODD_UNDER_3_5','ODD_BTTS_SIM','ODD_BTTS_NAO','LG_SCORE_CASA','LG_SCORE_VISITANTE','HSCORE','LG_SCORE']);
function importFieldName(h){const raw=String(h??'').trim();const n=normalizeImportHeader(raw);if(IMPORT_ALIASES[n])return IMPORT_ALIASES[n];const direct=raw.toUpperCase().replace(/\s+/g,'_');return IMPORT_KNOWN.has(direct)?direct:null}
function importValue(field,v){let x=String(v??'').trim();if(!x)return null;if(field==='DATA'){let m=x.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})/);if(m)return `${m[3]}-${String(m[2]).padStart(2,'0')}-${String(m[1]).padStart(2,'0')}`;m=x.match(/^(\d{4})[\/-](\d{1,2})[\/-](\d{1,2})/);if(m)return `${m[1]}-${String(m[2]).padStart(2,'0')}-${String(m[3]).padStart(2,'0')}`;return x}if(['HORA','CONFRONTO','CAMPEONATO'].includes(field))return x;const n=Number(x.replace(/\s/g,'').replace(',','.'));return Number.isFinite(n)?n:x}
function seasonLabel(v){const s=String(v??'');return ({'58766':'2024','72034':'2025','2026':'2026'}[s]||s)}
function inferImportSeason(fileName){const m=String(fileName||'').match(/(?:^|[^0-9])(2024|2025|2026)(?:[^0-9]|$)/);return m?({'2024':'58766','2025':'72034','2026':'2026'}[m[1]]||m[1]):null}
function prepareImportRows(parsed,fileName=''){const fields=parsed.headers.map(h=>({header:h,field:importFieldName(h)}));const rows=[];let errors=0;const inferredSeason=inferImportSeason(fileName);for(const source of parsed.rows){const out={};fields.forEach(({header,field})=>{if(field){const v=importValue(field,source[header]);if(v!==null)out[field]=v}});if(!out.TEMPORADA&&inferredSeason)out.TEMPORADA=inferredSeason;if(!out.DATA||!out.CONFRONTO||!out.CAMPEONATO){errors++;continue}delete out.id;rows.push(out)}return{rows,errors,fields}}
function setImportStatus(type,title,detail=''){const e=$('#importStatus');if(!e)return;e.className='importStatus '+type;e.innerHTML=`<span class="statusDot"></span><b>${esc(title)}</b>${detail?`<small>${esc(detail)}</small>`:''}`}
